//! The build script both apps share (`build = "../app-build.rs"` in their Cargo.toml).
//!
//! Windows: embeds `brand/<package>-icon.ico` as icon resource 1, which GPUI loads for its
//! windows, so the app has its icon in Explorer, the taskbar and the title bar. The .ico files are
//! generated by tools/gpui/make-icons.ts and committed. Other platforms: nothing.

fn main() {
    let package = std::env::var("CARGO_PKG_NAME").expect("CARGO_PKG_NAME");
    let ico = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(format!("../../../brand/{package}-icon.ico"));
    println!("cargo:rerun-if-changed={}", ico.display());
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows") {
        let rc = std::path::Path::new(&std::env::var("OUT_DIR").expect("OUT_DIR")).join("app.rc");
        let path = ico.display().to_string().replace('\\', "\\\\");
        std::fs::write(&rc, format!("1 ICON \"{path}\"\n")).expect("write app.rc");
        embed_resource::compile(&rc, embed_resource::NONE).manifest_required().expect("embed the app icon");
    }
}
